/** One package contribution understood only by the owner of its exact ABI. */
type Facet = {
    readonly abi: string;
    readonly offers?: readonly string[];
    readonly implementation: unknown;
};

type ModuleRef = {
    readonly name: string;
    readonly version: string;
};
/**
 * A Type is its owning Module and its name, and nothing else is compared. Two Types whose values
 * carry identical shapes are distinct, so one is refused where the other is declared — there is no
 * structural fallback to fall back to.
 */
type TypeRef = {
    readonly module: ModuleRef;
    readonly name: string;
};
type CapabilityRef = {
    readonly module: ModuleRef;
    readonly name: string;
};

type ModuleDependency = {
    readonly module: ModuleRef;
};
type TypeDeclaration = {
    readonly name: string;
};
type PortDeclaration = {
    readonly name: string;
    readonly type: TypeRef;
};
type NeedPortDeclaration = {
    readonly name: string;
    readonly capability: CapabilityRef;
    readonly returns: TypeRef;
};
type CapabilityDeclaration = {
    readonly name: string;
    readonly returns: TypeRef;
};
type ProducerDeclaration = {
    readonly name: string;
    readonly inputs: readonly PortDeclaration[];
    readonly outputs: readonly PortDeclaration[];
    readonly needs: readonly NeedPortDeclaration[];
};
type ModuleManifest = {
    readonly format: "hypit.module@1";
    readonly name: string;
    readonly version: string;
    readonly dependencies: readonly ModuleDependency[];
    readonly types: readonly TypeDeclaration[];
    readonly capabilities: readonly CapabilityDeclaration[];
    readonly producers: readonly ProducerDeclaration[];
};

/** Semantic Module declaration carried by one physical package. */
type ModuleContribution = {
    readonly manifest: ModuleManifest;
    /** Additional author import spellings resolved to this exact Manifest. */
    readonly specifiers?: readonly string[];
};
/** Opaque logical address resolved to an explicitly selected installed package. */
type LogicalPackageAddress = {
    readonly abi: string;
    readonly name: string;
};
/**
 * Executable facets exported by one installed physical package. The Host independently grants
 * each exact Facet ABI. Runtime facets remain inert unless a Runtime Profile selects the package.
 */
type PackageContribution = {
    readonly format: "hypit.package@1";
    readonly modules?: readonly ModuleContribution[];
    /** Executable contributions remain inert until the owner of their exact ABI selects them. */
    readonly facets?: readonly Facet[];
};
/** Physical owner established by the Host; executable code never self-asserts this identity. */
type LoadedPackage = {
    readonly specifier: string;
    readonly contribution: PackageContribution;
};

/** Validate declarations and logical offers without interpreting any executable Facet. */
declare function verifyPackageContributions(packages: readonly PackageContribution[]): void;

export { verifyPackageContributions };
export type { LoadedPackage, LogicalPackageAddress, ModuleContribution, PackageContribution };
